// Helper: strip HTML tags for clean description
function stripHtml(str) {
  if (!str) return ''
  return str
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .trim()
    .slice(0, 500)
}

// Helper: get first image URL from comma-separated list
function firstImage(images) {
  if (!images) return null
  return images.split(',')[0].trim() || null
}

// Helper: pick price (sale > regular, skip if both empty)
function getPrice(sale, regular) {
  const s = parseFloat(sale)
  const r = parseFloat(regular)
  if (!isNaN(s) && s > 0) return s
  if (!isNaN(r) && r > 0) return r
  return null
}

// Helper: clean category string
function cleanCategory(cat) {
  if (!cat) return 'General'
  // take first category if multiple, trim whitespace
  return cat.split(',')[0].replace(/&amp;/g, '&').trim() || 'General'
}

