// Filter out products with price 0 or null — set them to a default of 0
// and mark so admin can update later
const rows = products
  .filter(p => p.name && p.name.trim() !== '')
  .map(p => ({
    name: p.name.trim(),
    price: (p.price && p.price > 0) ? p.price : 0,
    image: p.image || null,
    description: p.description ? p.description.slice(0, 500) : '',
    category: p.category || 'General',
    stock: 10,
  }))

async function run() {
  console.log(`Inserting ${rows.length} products...`)

  // Insert in batches of 50 to avoid payload limits
  const BATCH = 50
  let total = 0

  for (let i = 0; i < rows.length; i += BATCH) {
    const batch = rows.slice(i, i + BATCH)
    const { data, error } = await supabase
      .from('products')
      .insert(batch)
      .select('name, price')

    if (error) {
      console.error(`Batch ${i}-${i + BATCH} error:`, error.message)
      if (error.details) console.error('Details:', error.details)
    } else {
      total += data.length
      data.forEach(p => console.log(`  ✓ ${p.name} — ${p.price.toLocaleString()}`))
    }
  }

  console.log(`\nDone. ${total} products inserted.`)
}

run()
